/*
 * prog41_series_sum – reconstructed from the supplied binary.
 *
 * Behaviour (identical to the original program):
 *   prog41_series_sum MODE LIMIT
 *
 *   * If fewer than three command‑line arguments are supplied → prints
 *     "NO_INPUT".
 *   * If either argument is not a valid decimal integer (or contains extra
 *     characters) → prints "BAD_INPUT".
 *   * If LIMIT is negative → prints "BAD_INPUT".
 *   * If LIMIT is greater than 100000 → prints "OUT_OF_RANGE".
 *   * MODE determines the series that is summed:
 *       MODE = 1 :  Σ_{i=1}^{LIMIT} 1.0/(i*i)          (Basel series)
 *       MODE = 2 :  Σ_{i=1}^{LIMIT} 1.0/i              (Harmonic series)
 *       MODE = 3 :  Σ_{i=0}^{LIMIT} 1.0/(i!)           (e‑series)
 *   * Any other MODE → prints "BAD_MODE".
 *   * The result is printed with six digits after the decimal point:
 *       printf("%.6f\n", result);
 *   * All messages are emitted with puts() exactly as they appear in the
 *     original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

/* Return 1 if the whole string represents a valid integer, 0 otherwise. */
static int whole_number(const char *s, char **endptr)
{
    if (s == NULL || *s == '\0')
        return 0;
    errno = 0;
    (void)strtol(s, endptr, 10);
    if (errno != 0)
        return 0;               /* overflow / underflow */
    return **endptr == '\0';   /* conversion consumed the whole string */
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    if (!whole_number(argv[1], &end1) || !whole_number(argv[2], &end2)) {
        puts("BAD_INPUT");
        return 0;
    }

    long mode  = strtol(argv[1], NULL, 10);
    long limit = strtol(argv[2], NULL, 10);

    if (limit < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    double result = 0.0;
    switch (mode) {
        case 1:   /* Basel series Σ 1/(i*i) */
            for (long i = 1; i <= limit; ++i) {
                result += 1.0 / ((double)i * (double)i);
            }
            break;
        case 2:   /* Harmonic series Σ 1/i */
            for (long i = 1; i <= limit; ++i) {
                result += 1.0 / (double)i;
            }
            break;
        case 3:   /* e‑series Σ 1/i! (starting with i=0) */
            result = 1.0;          /* term for i = 0 */
            double term = 1.0;
            for (long i = 1; i <= limit; ++i) {
                term /= (double)i;   /* term = 1/i! */
                result += term;
            }
            break;
        default:
            puts("BAD_MODE");
            return 0;
    }

    printf("%.6f\n", result);
    return 0;
}
